window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8de95285b1c27c9d"]={"versions": [{"id": "FIG-8de95285b1c27c9d", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Sequenzdiagramm in TTCN-3 GFT-Notation (<em>Graphical Presentation Format for TTCN-3</em>, ETSI ES 201 873-3 / ITU-T Z.163 MSC-Dialekt).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Conformance Testing Architecture (Dokument: <code>AUTOSAR_CTSpec_Creation_Validation</code>, Release R3.0.7).</li>\n<li><strong>Funktionaler Zweck:</strong> Prozedurale Interaktion zwischen der Testausführungsumgebung (<em>Test Case / Test Component</em>) und dem Zielsystem (<em>System Under Test</em>, SUT) über einen Target Adapter (TA). Spezifiziert das synchrone Auslesen eines zuvor auf dem Target allokierten Speicherblocks (BSW-Verifikationskontext, z. B. Test von Memory-Stacks wie NvM, Fee, Fls oder PDU-Puffern) zur Verifikation der Testergebnisse.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lebenslinien:</strong></li>\n<li><strong>Rechte Lebenslinie:</strong> TTCN-3 Testkomponente (MTC – <em>Main Test Component</em> bzw. PTC – <em>Parallel Test Component</em>), steuert den Testfallablauf.</li>\n<li><strong>Mittlere Vertikale:</strong> Systemgrenze / Schnittstellenabstraktion (<em>Test System Interface</em>, TSI) zwischen TTCN-3 Runtime und Test-Adapter-Ebene.</li>\n<li><strong>Linke Lebenslinie:</strong> Target Adapter (TA) / Target Agent; fungiert als Hardware- und Protokoll-Treiber zur physischen Zielhardware (via Debug-Interface, XCP, CAN oder BDM/JTAG).</li>\n<li><strong>Ports & Signatur-Schnittstellen:</strong></li>\n<li><code>pt_Ta</code>: Bidirektionaler, prozedurbasierter Kommunikationsport (<em>procedure-based port</em>) zur Anbindung des Testfalls an den Target Adapter.</li>\n<li><code>TA_ReadMemBlock</code>: Prozedursignatur für den synchronen Speicherlesezugriff auf dem Target.</li>\n<li><strong>Zustands- & Zeit-Entitäten:</strong></li>\n<li><code>t_guardtimer</code>: Lokaler TTCN-3 Guard-Timer (Watchdog) zur Absicherung gegen Blockaden bei nicht antwortendem Target.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Timer-Start (<code>t_guardtimer(30.0)</code>):</strong></li>\n</ol>\n<p class=\"fig-p\">Die Testkomponente startet den Guard-Timer mit einer Ablaufzeit von 30,0 Sekunden (symbolisiert durch das Sanduhr-Symbol).</p>\n<ol class=\"fig-list\">\n<li><strong>Prozeduraufruf (<code>call TA_ReadMemBlock</code>):</strong></li>\n</ol>\n<p class=\"fig-p\">Die Testkomponente sendet synchron über Port <code>pt_Ta</code> den Funktionsaufruf <code>TA_ReadMemBlock</code> an den Target Adapter. Der Aufruf transportiert Parameter wie Block-Identifier/Handle, Startadresse und Datenlänge.</p>\n<ol class=\"fig-list\">\n<li><strong>Ausführung auf dem Target:</strong></li>\n</ol>\n<p class=\"fig-p\">Der Target Adapter greift auf den adressierten physischen Speicherbereich des SUT zu.</p>\n<ol class=\"fig-list\">\n<li><strong>Antwortempfang (<code>get reply TA_ReadMemBlock</code>):</strong></li>\n</ol>\n<p class=\"fig-p\">Der Target Adapter liefert die ausgelesenen Nutzdaten sowie den Ausführungsstatus per Antwortnachricht über Port <code>pt_Ta</code> zurück an die Testkomponente.</p>\n<ol class=\"fig-list\">\n<li><strong>Template-Matching (<code>match TA_ReadMemBlock</code>):</strong></li>\n</ol>\n<p class=\"fig-p\">Der empfangene Nutzdatenstrom wird inline gegen das im Testfall definierte Soll-Muster (<em>TTCN-3 Template/Value</em>) validiert. Eine Diskrepanz führt zum Conformance-Urteil <code>fail</code>.</p>\n<ol class=\"fig-list\">\n<li><strong>Timer-Stopp (<code>X t_guardtimer(0.0060)</code>):</strong></li>\n</ol>\n<p class=\"fig-p\">Nach erfolgreichem Empfang und Validierung wird der Guard-Timer explizit angehalten (gekennzeichnet durch das Kreuz-Symbol; Zeitstempel/Restzeit: 0,0060 s).</p>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen-Vertrag für Test-Adapter-Entwickler:</strong></li>\n<li>Der Target Adapter muss den Call <code>TA_ReadMemBlock</code> blockierend oder mit deterministischer Rückmeldung implementieren.</li>\n<li>Der Guard-Timer von 30,0 s definiert die maximale Obergrenze inklusive Transport- und Auslesezeit; ein Timeout bricht den Testfall mit <code>inconc</code> (<em>inconclusive</em>) oder <code>fail</code> ab.</li>\n<li><strong>BSW- und Stack-Entwickler (Testbarkeit):</strong></li>\n<li>Voraussetzung für diesen Lesezugriff ist die vorherige Allokation des Blocks gemäß Kap. 11.4 (Figure 16). Ein Zugriff auf nicht initialisierte oder freigegebene Handles muss vom Target Agent mit einem definierten Fehlercode quittiert werden.</li>\n<li>Lesezugriffe über den Target Adapter auf Shared Memory oder Puffer unterliegen potenziellen Race Conditions mit aktiven BSW-Tasks (z. B. laufenden NvM-Schreibjobs). Testfälle müssen vor dem Aufruf sicherstellen, dass schreibende BSW-Operationen vollständig abgeschlossen sind (<code>MEMIF_IDLE</code> / <code>NVM_REQ_OK</code>).</li>\n</ul>"}, {"id": "FIG-aa1eec5c70d99466", "releases": ["R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp:</strong> Sequenzdiagramm in TTCN-3 GFT-Notation (<em>Graphical Presentation Format for TTCN-3</em>, ETSI ES 201 873-3 / ITU-T Z.163 MSC-Dialekt).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Conformance Testing Architecture (Dokument: <code>AUTOSAR_CTSpec_Creation_Validation</code>, Release R3.0.7).</li>\n<li><strong>Funktionaler Zweck:</strong> Prozedurale Interaktion zwischen der Testausführungsumgebung (<em>Test Case / Test Component</em>) und dem Zielsystem (<em>System Under Test</em>, SUT) über einen Target Adapter (TA). Spezifiziert das synchrone Auslesen eines zuvor auf dem Target allokierten Speicherblocks (BSW-Verifikationskontext, z. B. Test von Memory-Stacks wie NvM, Fee, Fls oder PDU-Puffern) zur Verifikation der Testergebnisse.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Lebenslinien:</strong></li>\n<li><strong>Rechte Lebenslinie:</strong> TTCN-3 Testkomponente (MTC – <em>Main Test Component</em> bzw. PTC – <em>Parallel Test Component</em>), steuert den Testfallablauf.</li>\n<li><strong>Mittlere Vertikale:</strong> Systemgrenze / Schnittstellenabstraktion (<em>Test System Interface</em>, TSI) zwischen TTCN-3 Runtime und Test-Adapter-Ebene.</li>\n<li><strong>Linke Lebenslinie:</strong> Target Adapter (TA) / Target Agent; fungiert als Hardware- und Protokoll-Treiber zur physischen Zielhardware (via Debug-Interface, XCP, CAN oder BDM/JTAG).</li>\n<li><strong>Ports & Signatur-Schnittstellen:</strong></li>\n<li><code>pt_Ta</code>: Bidirektionaler, prozedurbasierter Kommunikationsport (<em>procedure-based port</em>) zur Anbindung des Testfalls an den Target Adapter.</li>\n<li><code>TA_ReadMemBlock</code>: Prozedursignatur für den synchronen Speicherlesezugriff auf dem Target.</li>\n<li><strong>Zustands- & Zeit-Entitäten:</strong></li>\n<li><code>t_guardtimer</code>: Lokaler TTCN-3 Guard-Timer (Watchdog) zur Absicherung gegen Blockaden bei nicht antwortendem Target.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Timer-Start (<code>t_guardtimer(30.0)</code>):</strong></li>\n</ol>\n<p class=\"fig-p\">Die Testkomponente startet den Guard-Timer mit einer Ablaufzeit von 30,0 Sekunden (symbolisiert durch das Sanduhr-Symbol).</p>\n<ol class=\"fig-list\">\n<li><strong>Prozeduraufruf (<code>call TA_ReadMemBlock</code>):</strong></li>\n</ol>\n<p class=\"fig-p\">Die Testkomponente sendet synchron über Port <code>pt_Ta</code> den Funktionsaufruf <code>TA_ReadMemBlock</code> an den Target Adapter. Der Aufruf transportiert Parameter wie Block-Identifier/Handle, Startadresse und Datenlänge.</p>\n<ol class=\"fig-list\">\n<li><strong>Ausführung auf dem Target:</strong></li>\n</ol>\n<p class=\"fig-p\">Der Target Adapter greift auf den adressierten physischen Speicherbereich des SUT zu.</p>\n<ol class=\"fig-list\">\n<li><strong>Antwortempfang (<code>get reply TA_ReadMemBlock</code>):</strong></li>\n</ol>\n<p class=\"fig-p\">Der Target Adapter liefert die ausgelesenen Nutzdaten sowie den Ausführungsstatus per Antwortnachricht über Port <code>pt_Ta</code> zurück an die Testkomponente.</p>\n<ol class=\"fig-list\">\n<li><strong>Template-Matching (<code>match TA_ReadMemBlock</code>):</strong></li>\n</ol>\n<p class=\"fig-p\">Der empfangene Nutzdatenstrom wird inline gegen das im Testfall definierte Soll-Muster (<em>TTCN-3 Template/Value</em>) validiert. Eine Diskrepanz führt zum Conformance-Urteil <code>fail</code>.</p>\n<ol class=\"fig-list\">\n<li><strong>Timer-Stopp (<code>X t_guardtimer(0.0060)</code>):</strong></li>\n</ol>\n<p class=\"fig-p\">Nach erfolgreichem Empfang und Validierung wird der Guard-Timer explizit angehalten (gekennzeichnet durch das Kreuz-Symbol; Zeitstempel/Restzeit: 0,0060 s).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen-Vertrag für Test-Adapter-Entwickler:</strong></li>\n<li>Der Target Adapter muss den Call <code>TA_ReadMemBlock</code> blockierend oder mit deterministischer Rückmeldung implementieren.</li>\n<li>Der Guard-Timer von 30,0 s definiert die maximale Obergrenze inklusive Transport- und Auslesezeit; ein Timeout bricht den Testfall mit <code>inconc</code> (<em>inconclusive</em>) oder <code>fail</code> ab.</li>\n<li><strong>BSW- und Stack-Entwickler (Testbarkeit):</strong></li>\n<li>Voraussetzung für diesen Lesezugriff ist die vorherige Allokation des Blocks gemäß Kap. 11.4 (Figure 16). Ein Zugriff auf nicht initialisierte oder freigegebene Handles muss vom Target Agent mit einem definierten Fehlercode quittiert werden.</li>\n<li>Lesezugriffe über den Target Adapter auf Shared Memory oder Puffer unterliegen potenziellen Race Conditions mit aktiven BSW-Tasks (z. B. laufenden NvM-Schreibjobs). Testfälle müssen vor dem Aufruf sicherstellen, dass schreibende BSW-Operationen vollständig abgeschlossen sind (<code>MEMIF_IDLE</code> / <code>NVM_REQ_OK</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-8de95285b1c27c9d", "to": "FIG-aa1eec5c70d99466", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
